<?php get_header(); ?><div class="container content-layout"><div class="primary-content"><header class="archive-header"><p class="eyebrow"><?php esc_html_e( 'Explore', 'souqify' ); ?></p><h1><?php the_archive_title(); ?></h1><?php the_archive_description( '<div class="archive-description">', '</div>' ); ?></header><?php if ( have_posts() ) : ?><div class="posts-grid"><?php while ( have_posts() ) : the_post(); ?><article <?php post_class( 'post-card' ); ?>><a href="<?php the_permalink(); ?>"><?php if ( has_post_thumbnail() ) { the_post_thumbnail( 'medium_large', array( 'loading' => 'lazy' ) ); } ?></a><div class="post-card-body"><div class="post-meta"><?php echo esc_html( get_the_date() ); ?></div><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><a class="text-link" href="<?php the_permalink(); ?>"><?php esc_html_e( 'Read more', 'souqify' ); ?> →</a></div></article><?php endwhile; ?></div><?php souqify_pagination(); else : ?><p><?php esc_html_e( 'Nothing found.', 'souqify' ); ?></p><?php endif; ?></div><?php get_sidebar(); ?></div><?php get_footer(); ?>
